package dev.slithergoh.pixelmonradar.client;

import net.minecraft.client.Minecraft;import net.minecraft.core.BlockPos;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.level.block.Block;import java.util.*;
public final class OreScanner{private OreScanner(){}private static List<BlockPos>cached=List.of();private static long lastScan;private static BlockPos lastCenter=BlockPos.ZERO;private static int lastRange=-1;private static int lastSelectionHash;
 public static List<ResourceLocation>candidates(){ArrayList<ResourceLocation>out=new ArrayList<>();for(ResourceLocation id:BuiltInRegistries.BLOCK.keySet()){String p=id.getPath();if(p.contains("ore")||p.contains("bauxite")||p.contains("ruby")||p.contains("sapphire")||p.contains("platinum")||p.contains("silver")||p.contains("silicon")||p.contains("crystal"))out.add(id);}out.sort(Comparator.comparing(ResourceLocation::toString));return out;}
 public static List<BlockPos>scan(){Minecraft mc=Minecraft.getInstance();if(mc.level==null||mc.player==null||RadarSettings.selectedOres.isEmpty())return List.of();long now=System.currentTimeMillis();int r=RadarSettings.oreRange,hash=RadarSettings.selectedOres.hashCode();BlockPos c=mc.player.blockPosition();boolean moved=c.distManhattan(lastCenter)>4;if(!moved&&r==lastRange&&hash==lastSelectionHash&&now-lastScan<1800)return cached;lastScan=now;lastCenter=c;lastRange=r;lastSelectionHash=hash;ArrayList<BlockPos>found=new ArrayList<>();int minY=Math.max(mc.level.getMinBuildHeight(),c.getY()-r),maxY=Math.min(mc.level.getMaxBuildHeight()-1,c.getY()+r);for(int y=minY;y<=maxY;y++)for(int z=c.getZ()-r;z<=c.getZ()+r;z++)for(int x=c.getX()-r;x<=c.getX()+r;x++){BlockPos p=new BlockPos(x,y,z);if(!mc.level.hasChunkAt(p))continue;Block b=mc.level.getBlockState(p).getBlock();ResourceLocation id=BuiltInRegistries.BLOCK.getKey(b);if(RadarSettings.selectedOres.contains(id.toString()))found.add(p);if(found.size()>=2500){cached=sort(found,c);return cached;}}cached=sort(found,c);return cached;}
 private static List<BlockPos>sort(List<BlockPos>f,BlockPos c){f.sort(Comparator.comparingDouble(p->p.distSqr(c)));return List.copyOf(f);}
}
